int counts[11][331];

void solve(int n, int i, int m, int s) {
    if (i == 0) {
        counts[m][s]++;
        return;
    }
    for (int j = 0; j < 10; j++) {
        if ((n & 1 << j) == 0) {
            solve(n | 1 << j, i - 1, m, s + i * j);
        }
    }
}

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        for (int i = 1; i < 11; i++) {
            solve(0, i, i, 0);
        }

        NSFileHandle *fileHandle = [NSFileHandle fileHandleForReadingAtPath:@"/dev/stdin"];
        NSData *data = [fileHandle readDataToEndOfFile];
        NSString *input = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];

        NSArray *lines = [input componentsSeparatedByString:@"\n"];
        for (NSString *line in lines) {
            if ([line isEqualToString:@""]) {
                break;
            }

            NSArray *numbers = [line componentsSeparatedByString:@" "];
            int n = [numbers[0] intValue];
            int s = [numbers[1] intValue];
            if (s > 330) {
                NSLog(@"0");
            } else {
                NSLog(@"%d", counts[n][s]);
            }
        }
    }
    return 0;
}

#import <Foundation/Foundation.h>

int solve(int n, int s, BOOL *check) {
    if (n > 10) {
        return 0;
    }
    if (s > n*(n+1)*(28-n)/3) {
        return 0;
    }
    int a = s/n;
    if (a > 9) {
        a = 9;
    }
    if (n == 1) {
        if (s > 9 || check[s]) {
            return 0;
        } else {
            return 1;
        }
    }
    int count = 0;
    for (int i = a; i >= 0; i--) {
        if (check[i]) {
            continue;
        }
        check[i] = YES;
        count += solve(n-1, s-i*n, check);
        check[i] = NO;
    }
    return count;
}

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        NSString *inputString = [NSString stringWithContentsOfFile:@"/dev/stdin" encoding:NSUTF8StringEncoding error:nil];
        NSArray *lines = [inputString componentsSeparatedByString:@"\n"];
        NSMutableArray *result = [NSMutableArray array];

        for (NSString *line in lines) {
            if ([line length] == 0) {
                break;
            }
            NSArray *numbers = [line componentsSeparatedByString:@" "];
            int n = [numbers[0] intValue];
            int s = [numbers[1] intValue];

            BOOL *check = (BOOL *)calloc(10, sizeof(BOOL));
            int count = solve(n, s, check);
            free(check);
            [result addObject:[NSNumber numberWithInt:count]];
        }

        for (NSNumber *sum in result) {
            NSLog(@"%@", sum);
        }
    }
    return 0;
}

