        if (i < 0 || i > 7 || j < 0 || j > 7)
            return;
        if (map[i][j] == 1) {
            map[i][j] = 0;
            for (int x = 1; x <= 3; x++) {
                explosion(i + x, j);
                explosion(i - x, j);
