int main(int argc, const char * argv[]) {
    @autoreleasepool {
        int h, m, s, a, b;
        NSString *ans[3];
        NSString *ans2[3];

        while (true) {
            scanf("%d %d %d", &h, &m, &s);
            if (h == -1 && m == -1 && s == -1) break;

            a = h * 3600 + m * 60 + s;
            a = 120 * 60 - a;
            b = a * 3;

            if (a / 3600 == 0)
                ans[0] = @"00";
            else if (a / 3600 < 10)
                ans[0] = [NSString stringWithFormat:@"0%@", @(a / 3600)];
            else
                ans[0] = @(a / 3600);

            a = a % 3600;

            if (b / 3600 == 0)
                ans2[0] = @"00";
            else if (b / 3600 < 10)
                ans2[0] = [NSString stringWithFormat:@"0%@", @(b / 3600)];
            else
                ans2[0] = @(b / 3600);

            b = b % 3600;

            if (a / 60 == 0)
                ans[1] = @"00";
            else if (a / 60 < 10)
                ans[1] = [NSString stringWithFormat:@"0%@", @(a / 60)];
            else
                ans[1] = @(a / 60);

            a = a % 60;

            if (b / 60 == 0)
                ans2[1] = @"00";
            else if (b / 60 < 10)
                ans2[1] = [NSString stringWithFormat:@"0%@", @(b / 60)];
            else
                ans2[1] = @(b / 60);

            b = b % 60;

            if (a == 0)
                ans[2] = @"00";
            else if (a < 10)
                ans[2] = [NSString stringWithFormat:@"0%@", @(a)];
            else
                ans[2] = @(a);

            if (b == 0)
                ans2[2] = @"00";
            else if (b < 10)
                ans2[2] = [NSString stringWithFormat:@"0%@", @(b)];
            else
                ans2[2] = @(b);

            NSLog(@"%@:%@:%@", ans[0], ans[1], ans[2]);
            NSLog(@"%@:%@:%@", ans2[0], ans2[1], ans2[2]);
        }
    }
    return 0;
}

